with.script:
const pr = context.payload.pull_request.number;
const stage = process.env.STAGE;
const status = process.env.DEPLOY_STATUS;
const runUrl = `https://github.com/${context.repo.owner}/${context.repo.repo}/actions/runs/${context.runId}`;
const icon = status === 'success' ? '✅' : '❌';
const body = [
  `## ${icon} Preview Deployment`,
  '',
  `| Item | Value |`,
  `|------|-------|`,
  `| Stage | \`${stage}\` |`,
  `| Status | ${status} |`,
  `| Region | \`${process.env.AWS_REGION}\` |`,
  `| Run | [View logs](${runUrl}) |`,
  '',
  `SSM parameters deployed by this stage: \`/mem9-on-aws/${stage}/...\``,
  '',
  `*The preview is removed automatically when the PR is closed.*`,
].join('\n');
const { data: comments } = await github.rest.issues.listComments({
  owner: context.repo.owner,
  repo: context.repo.repo,
  issue_number: pr,
});
const existing = comments.find(c =>
  c.user.type === 'Bot' && c.body.includes('Preview Deployment')
);
if (existing) {
  await github.rest.issues.updateComment({
    owner: context.repo.owner,
    repo: context.repo.repo,
    comment_id: existing.id,
    body,
  });
} else {
  await github.rest.issues.createComment({
    owner: context.repo.owner,
    repo: context.repo.repo,
    issue_number: pr,
    body,
  });
}

steps.run:
node --input-type=module <<'JS'
import {execFileSync} from 'node:child_process';
const stage=process.env.STAGE,sha=process.env.GITHUB_SHA;
if(stage!=='prod'){
  const pr=JSON.parse(execFileSync('gh',['pr','view',stage.slice(3),'--json','headRefOid,isCrossRepository,state'],{encoding:'utf8'}));
  if(pr.isCrossRepository||pr.state!=='OPEN'||pr.headRefOid!==sha)throw Error('PreviewRevisionMismatch');
}
const runs=JSON.parse(execFileSync('gh',['run','list','--workflow','Infra CI','--commit',sha,'--limit','20','--json','databaseId,status,conclusion'],{encoding:'utf8'}));
let verified=false;
for(const run of runs.filter(r=>r.status==='completed'&&r.conclusion==='success')){
  const info=JSON.parse(execFileSync('gh',['run','view',String(run.databaseId),'--json','jobs'],{encoding:'utf8'}));
  if(info.jobs.some(j=>j.name===(stage==='prod'?'Deploy prod':'Deploy PR Preview')&&j.conclusion==='success')){verified=true;break;}
}
if(!verified)throw Error('VerifiedDeploymentRequired');
